// TH18 v1.00a Stage02 MainSub02 (st02.ecl:1144-1163) -> Cir00 (st02.ecl:6-31) + Cir00_at (32-71).
// Ranks are resolved from global(GVAR_RANK): Easy/N/H use the !E/!N/!H values, L uses the !LO value.
const TIME_LIMIT: int = 1400;
const OPENING_BUFFER: int = 120;
const TH18_BALL2: int = 432; // source etSprite(0,5,4): type5 Ball2, color4, base radius 4

// Source Cir00_at (st02:32-71): one aimed single-road shot per etOn; 3 emissions on N/H/L, 1 on Easy.
// Initial wait and inter-shot wait use the actual per-rank source branches.
async sub shooter() {
    var rank: int = global(GVAR_RANK);
    var wait0: int = 0;
    if rank == 0 { wait0 = 10 + rand(1000); } // st02:36
    if rank == 1 { wait0 = 10 + rand(60); }   // st02:38
    if rank == 2 { wait0 = 10 + rand(10); }   // st02:40
    if rank == 3 { wait0 = 10 + rand(10); }   // st02:42 (!LO -> L)
    wait(wait0);
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, 4);
    sh_aim(0, 1);                 // etAim(0,0): aimed fan, one road
    sh_ring(0, 0);
    sh_angle(0, 0deg, 0deg);      // etAngle(0,0,0)
    var shots: int = 1;
    if rank >= 1 { shots = 3; }   // diffI($A,1,3,3,3) at st02:53
    var i: int = 0;
    loop {
        // etCountD (st02:48): 1 road / 1 layer for E/N/H; 1 road / 2 layers for L.
        // etSpeedD (st02:50): E1,N2,H3,L(4,1); layers M=2 give speeds 4 and 1.
        if rank == 3 {
            sh_count(0, 1, 1);
            sh_speed(0, 4fx, 0fx);
            sh_dist(0, -16fx);    // ANIM a=1: spawn position -= 4*velocity (speed4 layer)
            sh_fire(0);
            sh_speed(0, 1fx, 0fx);
            sh_dist(0, -4fx);     // speed1 layer retreats 4px
            sh_fire(0);
        } else {
            var sp: fx = 1fx;
            if rank == 1 { sp = 2fx; }
            if rank == 2 { sp = 3fx; }
            sh_count(0, 1, 1);
            sh_speed(0, sp, 0fx);
            sh_dist(0, -4fx*sp);  // ANIM a=1 retreat kept, birth animation/no-hit window omitted
            sh_fire(0);
        }
        i = i + 1;
        // st02:57-66: the random wait is also executed after the last etOn before return.
        var gap: int = 0;
        if rank == 0 { gap = 10 + rand(200); }
        if rank == 1 { gap = 10 + rand(60); }
        if rank == 2 { gap = 10 + rand(10); }
        if rank == 3 { gap = 10 + rand(10); }
        wait(gap);
        if i >= shots { return; }
    }
}

// Source Cir00 (st02:6-31). ABS movement: moveVel(90..100deg, 3), linear speed 3->0.5 over 120f,
// then at t=180 linear speed 0.5->1 over 120f and shortest-arc turn to ANGLE_PLAYER over 120f.
// REL movement: moveEllipseRel(RANDRAD, 2deg/f, r=20, d=0, beta=ABS_ANGLE, s=0) -> 20px sine offset.
// The two position layers are combined explicitly per frame (circular-motion recipe).
async sub cir00() {
    set_invuln(65535);
    set_hurtbox(14fx); // setHurtbox(28,28): circular damage takes first value * 0.5
    set_hitbox(8fx);   // setHitbox(16,16): same half-width radius convention as existing cards
    // st02:17 moveVel(1.5707964 + RANDF2*0.17453292, 3.0): 90deg + [0,10)deg, speed 3.
    var u: fx = ((rand(65536) - 32768) as fx) / 65536 + 0.5fx;
    var h0: int = 16384 + (u * 1820fx) as int;
    // st02:19 moveEllipseRel(%RANDRAD, 0.034906585, 20, 0, %ABS_ANGLE, 0): beta is the live ABS angle.
    var th: int = rand(65536);
    var beta: int = h0;
    var ax: fx = $self_x;
    var ay: fx = $self_y;
    var spd: fx = 3fx;
    var ah: int = h0;
    var atgt: int = 0;
    var f: int = 0;
    spawn shooter();
    loop {
        // st02:18 moveSpeedTime(120,0,0.5) then st02:22 moveSpeedTime(120,0,1.0).
        if f < 120 { spd = 3fx - 2.5fx * (f as fx) / 120fx; }
        if f >= 120 && f < 180 { spd = 0.5fx; }
        if f >= 180 && f < 300 { spd = 0.5fx + 0.5fx * ((f-180) as fx) / 120fx; }
        if f >= 300 { spd = 1fx; }
        // st02:23 moveAngleTime(120,0,ANGLE_PLAYER): direction sampled at t=180, shortest arc.
        if f == 180 { atgt = aim_player() as int; }
        if f >= 180 {
            var d: int = atgt - h0;
            if d > 32768 { d = d - 65536; }
            if d <= -32768 { d = d + 65536; }
            if f < 300 { ah = h0 + d * (f-180) / 120; }
            else { ah = h0 + d; }
        }
        ax = ax + spd * cos((ah as angle));
        ay = ay + spd * sin((ah as angle));
        th = th + 364; // 0.034906585 rad/frame = 2deg/frame
        var m: fx = 20fx * sin(((th - beta) as angle));
        var ox: fx = -m * sin((beta as angle));
        var oy: fx = m * cos((beta as angle));
        move_to(0, ax + ox, ay + oy, EASE_LINEAR);
        wait(1);
        f = f + 1;
    }
}

// st02:1150-1158: five creates per round at x = base + RANDF2*64, y=-48, 20 frames apart.
sub spawn_one(x0: fx) {
    var u: fx = ((rand(65536) - 32768) as fx) / 65536 + 0.5fx;
    _ = spawn_enemy(x0 + 64fx * u, -48fx, 140, 0, 0, 0, cir00);
}

async sub wave() {
    wait(OPENING_BUFFER);
    for r in 0..8 {
        spawn_one(0fx);
        wait(20);
        spawn_one(64fx);
        wait(20);
        spawn_one(-64fx);
        wait(20);
        spawn_one(-120fx);
        wait(20);
        spawn_one(120fx);
        wait(20);
    }
    wait(TIME_LIMIT - OPENING_BUFFER);
    loop { wait(600); }
}

// Training-only phase owner at (0,0), no body collision; real enemies keep source hitbox/hurtbox.
async sub encounter() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
